sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var AUDIT = 'x_gegis_ins_policy_extraction_field_audit';
    var COL = 'manual_value';
    var MAX = 100;                       // audit old_value / new_value width

    var isNew = current.isNewRecord();
    var newValue = String(current.getValue(COL) || '');
    var oldValue = isNew ? '' : String(previous.getValue(COL) || '');

    // only a real change to manual_value is a revision - editing review_status,
    // confidence or anything else must not burn a version number
    if (isNew ? !newValue : (newValue === oldValue))
        return;

    // version is stamped in this same write - no second update(), so no
    // recursion back into this rule
    var version = isNew ? 1 : (parseInt(previous.getValue('version'), 10) || 1) + 1;
    current.setValue('version', version);

    var audit = new GlideRecord(AUDIT);
    if (!audit.isValid()) {
        gs.error('[extraction_field] ' + AUDIT + ' is missing - ' + COL
            + ' change on ' + current.getUniqueValue() + ' was NOT audited');
        return;
    }

    audit.initialize();
    audit.setValue('version', version);
    // sys_id is assigned before a before-insert rule runs, so this is the id the
    // row is about to be saved under
    audit.setValue('extraction_field', current.getUniqueValue());
    audit.setValue('changed_field', COL);
    audit.setValue('old_value', oldValue.substring(0, MAX));
    audit.setValue('new_value', newValue.substring(0, MAX));
    audit.setValue('changed_by', gs.getUserID());
    audit.setValue('changed_on', new GlideDateTime());
    audit.insert();

})(current, previous);
